<?php
require '../includes/init.php';requireLogin('admin');
$projects=$pdo->query('SELECT p.id,p.title,p.tech_stack,p.created_at,u.full_name,u.email,c.category_name FROM projects p JOIN users u ON u.id=p.user_id JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC')->fetchAll();
$assignments=$pdo->query('SELECT s.id,s.original_name,s.created_at,u.full_name,u.email,a.title FROM submissions s JOIN users u ON u.id=s.user_id JOIN assignments a ON a.id=s.assignment_id ORDER BY s.created_at DESC')->fetchAll();
$pageTitle='All Submissions';require '../includes/header.php'; ?>
<div class="d-flex justify-content-between"><h1>All Student Submissions</h1><span class="badge bg-primary align-self-start">Total: <?= count($projects)+count($assignments) ?> files</span></div>
<div class="panel table-responsive mb-4"><h2>Portfolio & FYP Projects</h2><table class="table table-striped"><thead class="table-dark"><tr><th>Student Name</th><th>Project Title</th><th>Category</th><th>Tech Stack</th><th>Submitted File</th><th>Date</th></tr></thead><tbody><?php foreach($projects as $r):?><tr><td><?= e($r['full_name']) ?><div class="small text-muted"><?= e($r['email']) ?></div></td><td><?= e($r['title']) ?></td><td><span class="badge bg-secondary"><?= e($r['category_name']) ?></span></td><td><?= e($r['tech_stack']) ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= BASE_URL ?>/download.php?type=project&id=<?= (int)$r['id'] ?>">⬇ File</a></td><td><?= e($r['created_at']) ?></td></tr><?php endforeach; ?><?php if(!$projects):?><tr><td colspan="6">No projects yet.</td></tr><?php endif; ?></tbody></table></div>
<div class="panel table-responsive"><h2>Assignment Submissions</h2><table class="table table-striped"><thead class="table-dark"><tr><th>Student</th><th>Assignment</th><th>Filename</th><th>Date</th><th>Download</th></tr></thead><tbody><?php foreach($assignments as $r):?><tr><td><?= e($r['full_name']) ?><div class="small"><?= e($r['email']) ?></div></td><td><?= e($r['title']) ?></td><td><?= e($r['original_name']) ?></td><td><?= e($r['created_at']) ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= BASE_URL ?>/download.php?type=submission&id=<?= (int)$r['id'] ?>">⬇ File</a></td></tr><?php endforeach; ?><?php if(!$assignments):?><tr><td colspan="5">No assignment submissions yet.</td></tr><?php endif; ?></tbody></table></div>
